--           客户端默认字符集可能是 latin1；文件头已放 SET NAMES utf8mb4 兜底，
--           否则中文地址会被按 latin1 存储成乱码、城市名无法被估值链解析。
-- ============================================================================

SET NAMES utf8mb4;

USE spacefin;












